NodeDiskUsageHigh.expr:
((max by (cluster, node, instance, device, mountpoint) (
  (
    100 * (
      node_filesystem_size_bytes{job="node-exporter", mountpoint!="", mountpoint!~"", fstype!~"|tmpfs|devtmpfs|overlay|squashfs|aufs|nsfs|proc|sysfs|cgroup2?|devpts|ramfs|tracefs|debugfs|securityfs|pstore|configfs|fusectl|mqueue|hugetlbfs"}
      - node_filesystem_avail_bytes{job="node-exporter"}
    ) / (node_filesystem_size_bytes{job="node-exporter"} > 0)
  )
  and (node_filesystem_readonly{job="node-exporter"} == 0)
)) >= 80) < 95

